parameters.jsCode:
const items = $input.all();

return items.map((item) => {
  // Combine all Gemini response parts
  const raw = (item.json.content?.parts ?? [])
    .filter(part => !part.thought && typeof part.text === 'string')
    .map(part => part.text)
    .join('');

  if (!raw.trim()) {
    throw new Error('Gemini returned an empty response.');
  }

  // Remove optional Markdown code fences
  const cleaned = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '');

  let result;

  try {
    result = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      'Invalid JSON returned by Gemini: ' + error.message
    );
  }

  // Validate the response structure
  if (
    !result ||
    typeof result.answer !== 'string' ||
    !result.answer.trim() ||
    typeof result.found_in_document !== 'boolean' ||
    !Array.isArray(result.evidence) ||
    !result.evidence.every(e => typeof e === 'string')
  ) {
    throw new Error('Invalid AI response structure.');
  }

  return {
    json: {
      question: $('On form submission').first().json['Your Question'],
      answer: result.answer,
      found_in_document: result.found_in_document,
      evidence: result.evidence
    }
  };
});

