$json.question +

"\n\nAI ANSWER\n\n" +
$json.answer +

"\n\nDOCUMENT STATUS\n\n" +
(
  $json.found_in_document
    ? "✅ Answer found in the document."
    : "⚠️ Insufficient information in the document."
) +

"\n\nSUPPORTING EVIDENCE\n\n" +
(
  $json.evidence.length > 0
    ? $json.evidence.map((quote, index) =>
        (index + 1) + ". " + quote
      ).join("\n\n")
    : "No supporting evidence found."
)
}}
